  ('endotherm', '/ˈɛn.ðəˌθɜrm/', '温血动物', 'An animal that maintains a constant body temperature regardless of environment.'),
  ('plash', '/plæʃ/', '水声；潺潺声', 'A sound made by water splashing or striking something.'),
  ('ultrasonics', '/ˌʌltrəˈsɒnɪks/', '超声波学', 'The study of sound waves above the audible range.'),
  ('tumid', '/ˈtjuː.mɪd/', '肿胀的；膨胀的', 'Swollen or distended, especially due to fluid accumulation.'),
  ('veining', '/ˈveɪ.nɪŋ/', '脉络；纹理', 'Patterns or lines that resemble veins in various contexts.'),
  ('unscrupulously', '/ʌnˈskruː.pjə.ləs.li/', '肆无忌惮地', 'In a manner lacking moral principles or ethics.'),
  ('warrantable', '/ˈwɔːr.ən.tə.bəl/', '合理的；可担保的', 'Justifiable or defensible in terms of reasoning or evidence.'),
  ('weaverbird', '/ˈwiː.vər.bɜːrd/', '织鸟', 'A bird known for its intricate nest-building techniques.'),
  ('vitalist', '/ˈvaɪ.təl.ɪst/', '生命主义者', 'A proponent of the theory that life processes are vital to existence.'),
  ('fowl', '/faʊl/', '家禽', 'Domestic birds raised for food or sport, especially chickens and ducks.'),
  ('ion', '/ˈaɪ.ɒn/', '离子', 'A charged particle resulting from the loss or gain of electrons.'),
  ('deport', '/dɪˈpɔrt/', '驱逐，放逐', 'To expel a person from a country.'),
  ('indent', '/ɪnˈdɛnt/', '缩进', 'To set in from the margin, usually for formatting text.'),
  ('avant-garde', '/ˌɑː.vɒ̃ˈɡɑːrd/', '先锋派艺术；前卫派艺术', 'A movement favoring experimental and innovative ideas in art and culture.'),
  ('perennially', '/pəˈrɛn.i.ə.li/', '持续不断地', 'In a way that lasts for a long time or perpetually.'),
  ('baby-sitter', '/ˈbeɪ.biˌsɪt.ər/', '保姆', 'A person who takes care of children temporarily.'),
  ('disillusion', '/ˌdɪs.ɪˈluː.ʒən/', '幻灭；失望', 'The feeling of disappointment after discovering something is not as good as believed.'),
  ('broad-brimmed', '/brɔd.brɪmd/', '宽边的', 'Having a wide brim, typically referring to hats.'),
  ('by-product', '/ˈbaɪˌprɒdʌkt/', '副产品', 'A secondary result produced during a process.'),
  ('eye-catching', '/ˈaɪˌkætʃ.ɪŋ/', '引人注目的', 'Attractive or striking in appearance, drawing attention.'),
  ('far-reaching', '/fɑːrˈriː.tʃɪŋ/', '深远的', 'Having significant and widespread effects or influence.'),
  ('hands-on', '/ˈhændzˌɔːn/', '实践的；动手的', 'Involving active participation or practical experience rather than theory.'),
  ('cast-iron', '/ˈkæstˌaɪərn/', '铸铁的', 'Made of iron that has been cast into a shape.'),
  ('long-range', '/lɔŋˈreɪndʒ/', '长距离的', 'Relating to or extending over a long distance or duration.'),
  ('long-lasting', '/ˈlɔːŋˌlæs.tɪŋ/', '持久的；耐久的', 'Durable, enduring for a long time without deterioration.'),
  ('self-sufficient', '/ˌsɛlf səˈfɪʃənt/', '自给自足的', 'Able to provide for oneself without external assistance.'),
  ('thousand-fold', '/ˈθaʊ.zənd.foʊld/', '千倍的；千重的', 'Involving or resulting in a thousand times increase or multiplication.'),
  ('teens', '/tiːnz/', '青少年', 'Young people typically aged between 13 and 19 years.'),
  ('long-standing', '/lɔːŋˈstændɪŋ/', '长期存在的', 'Existing for a long time; not recent or temporary.'),
  ('short-range', '/ʃɔrt-reɪndʒ/', '短程的', 'Pertaining to a limited distance or range.'),
  ('time-consuming', '/ˈtaɪm kənˌsjuːmɪŋ/', '费时间的', 'Requiring a significant amount of time to complete or accomplish.'),
  ('well-being', '/ˈwɛlˌbi.ɪŋ/', '幸福；健康', 'The state of being comfortable, healthy, or happy.'),
  ('wedge-shaped', '/ˈwɛdʒʃeɪpt/', '楔形的', 'Having the shape of a wedge, tapering at one end.'),
  ('three-dimensional', '/θriː.dɪˈmɛn.ʃən.əl/', '立体的', 'Having height, width, and depth; not flat or two-dimensional.')
  ) AS v(headword, ipa, def_zh, def_en)
 WHERE lower(w.headword) = v.headword;

INSERT INTO vocab_examples (word_id, sort_order, collocation, sentence, translation_zh, scene)
SELECT w.id, v.sort_order, v.collocation, v.sentence, v.translation_zh, v.scene
  FROM (VALUES
  ('unobstructed', 1, 'unobstructed view', 'Visitors can enjoy an unobstructed view of the beautiful landscape from the balcony.', '游客可以从阳台欣赏到美丽景色的畅通无阻的视野。', 'daily_life'),
  ('unobstructed', 2, 'unobstructed access', 'Employees require unobstructed access to all workstations for optimal productivity.', '员工需要畅通无阻的进入所有工作站，以实现最佳生产力。', 'work'),
  ('unobstructed', 3, 'unobstructed flow', 'The researchers ensured an unobstructed flow of data throughout the experiment.', '研究人员确保实验中数据的畅通无阻。', 'science_tech'),
  ('synchronous', 1, 'synchronous communication', 'Effective synchronous communication is essential for remote teams to collaborate successfully.', '有效的同步沟通对远程团队成功合作至关重要。', 'work'),
  ('synchronous', 2, 'synchronous learning', 'Synchronous learning environments allow students to interact in real-time during classes.', '同步学习环境使学生在上课期间能够实时互动。', 'education'),
  ('synchronous', 3, 'synchronous events', 'Scientists often study synchronous events in ecosystems to understand complex interactions.', '科学家通常研究生态系统中的同步事件，以了解复杂的相互作用。', 'science_tech'),
  ('cellulose', 1, 'cellulose fibers', 'Researchers are developing biodegradable plastics from cellulose fibers to reduce pollution.', '研究人员正在开发由纤维素纤维制成的生物可降解塑料，以减少污染。', 'science_tech'),
  ('cellulose', 2, 'cellulose content', 'Foods high in cellulose content can improve digestive health and prevent constipation.', '富含纤维素的食物可以改善消化健康，预防便秘。', 'health'),
  ('cellulose', 3, 'cellulose derivatives', 'The study analyzed the properties of various cellulose derivatives for industrial applications.', '该研究分析了不同纤维素衍生物在工业应用中的性质。', 'academic'),
  ('pliable', 1, 'pliable materials', 'Innovative engineers often use pliable materials to create flexible designs.', '创新的工程师经常使用柔韧的材料来创造灵活的设计。', 'science_tech'),
  ('pliable', 2, 'pliable mind', 'Students with a pliable mind can adapt to new concepts and ideas quickly.', '思维灵活的学生能够快速适应新的概念和想法。', 'education'),
  ('pliable', 3, 'pliable personality', 'Her pliable personality makes it easy for her to get along with others.', '她柔韧的性格使她容易与他人相处。', 'daily_life'),
  ('girdle', 1, 'girdle of the Earth', 'Scientists often refer to the girdle of the Earth when discussing its geology.', '科学家在讨论地质时，经常提到地球的束带。', 'science_tech'),
  ('girdle', 2, 'girdle your loins', 'Before facing the challenge, you should girdle your loins and prepare yourself mentally.', '在面对挑战之前，你应该束紧腰带，做好心理准备。', 'daily_life'),
  ('girdle', 3, 'girdles of armor', 'Ancient warriors used girdles of armor for additional protection during battles.', '古代战士在战斗中使用束带铠甲以提供额外的保护。', 'culture'),
  ('terminus', 1, 'bus terminus', 'Passengers waited at the bus terminus for their scheduled departures.', '乘客在公交终点站等待发车。', 'daily_life'),
  ('terminus', 2, 'train terminus', 'The train terminus was bustling with travelers and their luggage.', '火车终点站熙熙攘攘，充满了旅客和行李。', 'travel'),
  ('terminus', 3, 'terminus of a journey', 'Every student dreams of reaching the terminus of a journey toward knowledge.', '每个学生都梦想着抵达追求知识的终点。', 'education'),
  ('brownish', 1, 'brownish color', 'Many artists prefer using a brownish color to create a warm atmosphere in their works.', '许多艺术家偏爱使用棕色调来营造作品中的温暖氛围。', 'culture'),
  ('brownish', 2, 'brownish hue', 'In the evening light, the landscape appeared with a beautiful brownish hue that captivated everyone.', '在傍晚的光线中，景色呈现出一种迷人的棕色调，吸引了所有人。', 'daily_life'),
  ('brownish', 3, 'brownish tint', 'Scientists observed a brownish tint in the samples, indicating possible contamination during the study.', '科学家在样本中观察到了棕色的色调，表明在研究过程中可能存在污染。', 'science_tech'),
  ('roe', 1, 'salmon roe', 'Salmon roe is often served as a delicacy in Japanese cuisine.', '鲑鱼卵常作为日本料理中的美味佳肴。', 'culture'),
