  ('impersonation', 2, 'impersonation fraud', 'Employees must be aware of impersonation fraud attempts in the workplace.', '员工必须意识到工作场所中冒充欺诈的企图。', 'work'),
  ('impersonation', 3, 'celebrity impersonation', 'Many performers specialize in celebrity impersonation to entertain audiences at events.', '许多表演者专注于名人冒充，以在活动中娱乐观众。', 'culture'),
  ('torrential', 1, 'torrential rain', 'Floods often occur due to torrential rain during the monsoon season.', '在季风季节，倾泻而下的暴雨常常导致洪水。', 'environment'),
  ('torrential', 2, 'torrential downpour', 'A torrential downpour caused significant disruption to transportation services yesterday.', '昨天，猛烈的倾泻而下的雨水严重干扰了交通服务。', 'news'),
  ('torrential', 3, 'torrential flooding', 'Residents are advised to prepare for torrential flooding after the heavy storm warning issued.', '在发布强暴风雨警告后，居民被建议为倾泻而下的洪水做好准备。', 'daily_life'),
  ('badger', 1, 'badger someone', 'Friends tend to badger each other about their choices in life decisions.', '朋友们常常对彼此的生活选择进行纠缠。', 'daily_life'),
  ('badger', 2, 'badger into doing something', 'She was badgered into accepting the proposal despite her initial reluctance.', '尽管她最初不情愿，她还是被迫接受了提议。', 'work'),
