  ('three-dimensional', 1, 'three-dimensional models', 'Engineers often design three-dimensional models to visualize complex structures before construction.', '工程师们常常设计立体模型，以在施工前可视化复杂结构。', 'science_tech'),
  ('three-dimensional', 2, 'three-dimensional space', 'In mathematics, students learn about three-dimensional space and geometric concepts related to it.', '在数学课上，学生学习有关立体空间及其相关几何概念的内容。', 'education'),
  ('three-dimensional', 3, 'three-dimensional art', 'Artists are increasingly exploring three-dimensional art forms to enhance their creative expression.', '艺术家们越来越多地探索立体艺术形式，以增强他们的创造性表达。', 'culture')
  ) AS v(headword, sort_order, collocation, sentence, translation_zh, scene)
  JOIN vocab_words w ON lower(w.headword) = v.headword
ON CONFLICT (word_id, sort_order) DO UPDATE
  SET collocation = EXCLUDED.collocation,
      sentence = EXCLUDED.sentence,
      translation_zh = EXCLUDED.translation_zh,
      scene = EXCLUDED.scene;

SELECT 'p5/5 AFTER' AS stage,
       (SELECT count(*) FROM vocab_words WHERE def_zh IS NOT NULL) AS words_with_def,
       (SELECT count(*) FROM vocab_examples) AS examples;

-- ── 最后一片:总量 count-validate,五行都必须是 t,否则 ROLLBACK ──
SELECT 'words_with_def = 4471' AS expect,
       (SELECT count(*) FROM vocab_words WHERE def_zh IS NOT NULL) = 4471 AS ok
UNION ALL
SELECT 'examples = 13413',
       (SELECT count(*) FROM vocab_examples) = 13413
UNION ALL
SELECT '每个有释义的词恰好 3 条例句',
       NOT EXISTS (
         SELECT 1 FROM vocab_words w
          WHERE w.def_zh IS NOT NULL
            AND (SELECT count(*) FROM vocab_examples e WHERE e.word_id = w.id) <> 3
       )
UNION ALL
SELECT '每条例句的 scene 都在 10 值枚举内',
       NOT EXISTS (
         SELECT 1 FROM vocab_examples
          WHERE scene IS NULL OR scene NOT IN ('academic', 'news', 'daily_life', 'work', 'science_tech', 'health', 'environment', 'education', 'travel', 'culture')
       )
UNION ALL
SELECT '没有 def_zh 混入英文字母',
       NOT EXISTS (SELECT 1 FROM vocab_words WHERE def_zh ~ '[A-Za-z]');

COMMIT;
